import{c as o,Q as r,j as a,m as t}from"./chunks/framework.CgEMdeoU.js";const p=JSON.parse('{"title":"Free Tools for Freelancers — No Login, No Hosting","description":"A growing collection of free, browser-based tools for freelancers by Rahul Kewat (rahulkewat). No login, no signup, no hosting required.","frontmatter":{"title":"Free Tools for Freelancers — No Login, No Hosting","description":"A growing collection of free, browser-based tools for freelancers by Rahul Kewat (rahulkewat). No login, no signup, no hosting required.","head":[["meta",{"name":"keywords","content":"free freelancer tools, free portfolio builder, no-code freelancer tools, free website builder, Rahul Kewat tools, rahulkewat"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Free Tools for Freelancers — No Login, No Hosting"}],["meta",{"property":"og:description","content":"A growing collection of free, browser-based tools for freelancers. No login, no signup, no hosting required."}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"free-tools/index.md","filePath":"free-tools/index.md","lastUpdated":1779737623000}'),n={name:"free-tools/index.md"};function s(l,e,i,c,d,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="free-tools-for-freelancers" tabindex="-1">Free tools for freelancers <a class="header-anchor" href="#free-tools-for-freelancers" aria-label="Permalink to &quot;Free tools for freelancers&quot;">​</a></h1><p>A growing toolbox of <strong>100% free, browser-based tools</strong> for freelancers, indie hackers, and creators.</p><blockquote><p>No signup. No paywall. No data collected. Everything runs in your browser.</p></blockquote><h2 id="available-now" tabindex="-1">Available now <a class="header-anchor" href="#available-now" aria-label="Permalink to &quot;Available now&quot;">​</a></h2><div class="rk-tools-grid"><a class="rk-tool-card" href="/free-tools/website-builder/"><div class="rk-tool-card__icon">🪐</div><h3>Personal Website Builder</h3><p>Build a stunning, SEO-optimized personal website in minutes — no code, no login. Pick a template, edit live, download a single self-contained HTML file. Host it anywhere, even on a flash drive.</p><span class="rk-tool-card__badge">Live now</span></a><div class="rk-tool-card rk-tool-card--soon"><div class="rk-tool-card__icon">💸</div><h3>Freelance Rate Calculator</h3><p>Plug in your target income and expenses. Get the exact hourly + project rates you should charge.</p><span class="rk-tool-card__badge rk-tool-card__badge--soon">Coming soon</span></div><div class="rk-tool-card rk-tool-card--soon"><div class="rk-tool-card__icon">📝</div><h3>Proposal Generator</h3><p>Answer 8 questions, get a polished, client-ready proposal as a downloadable PDF.</p><span class="rk-tool-card__badge rk-tool-card__badge--soon">Coming soon</span></div><div class="rk-tool-card rk-tool-card--soon"><div class="rk-tool-card__icon">📄</div><h3>Invoice Generator</h3><p>Generate professional invoices with your branding. Download as PDF — no account, no watermark.</p><span class="rk-tool-card__badge rk-tool-card__badge--soon">Coming soon</span></div></div><h2 id="why-are-they-free" tabindex="-1">Why are they free? <a class="header-anchor" href="#why-are-they-free" aria-label="Permalink to &quot;Why are they free?&quot;">​</a></h2><p>Because the best way to build trust with freelancers is to <strong>give value first</strong>. These tools also serve as a small thank-you to the community that helped me cross my first $100k. If you find them useful, sharing them is the highest compliment you can give.</p><p>If you want to support the work, <a href="https://topmate.io/rahulkewat/1185547" target="_blank" rel="noreferrer">grab a 1:1 call</a> or read the <a href="/freelancing/">free freelancing playbook</a>.</p>',8)])])}const g=o(n,[["render",s]]);export{p as __pageData,g as default};
